 if(step==0){body.Children.Add(T("Quelques choix pour créer un espace qui vous ressemble. Vous pourrez tout modifier ensuite.",13,Muted,new Thickness(0,0,0,22)));var name=new TextBox{Text=settings.DisplayName,MaxLength=40};Field(body,"Votre prénom",name);var title=new TextBox{Text=settings.AppTitle,MaxLength=22};Field(body,"Nom de votre espace",title);var projects=new TextBox{Text=String.Join(Environment.NewLine,settings.Projects),AcceptsReturn=true,Height=100,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Field(body,"Premiers projets · un nom par ligne",projects);body.Children.Add(T("Votre espace est personnel. Le module bot Discord n’est pas activé par cet assistant.",12,Muted));capture=delegate{var names=projects.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(value=>value.Trim()).Where(value=>value.Length>0).Distinct().ToList();if(String.IsNullOrWhiteSpace(name.Text)||String.IsNullOrWhiteSpace(title.Text)||names.Count<1||names.Count>30||names.Any(value=>value.Length>80)){error.Text="Indiquez votre prénom, le nom de l’espace et entre 1 et 30 projets.";error.BringIntoView();return false;}settings.DisplayName=name.Text.Trim();settings.AppTitle=title.Text.Trim();settings.Projects=names;return true;};}
 else if(step==1){var choices=new List<ThemeChoice>{new ThemeChoice{Label="Actuel · "+settings.Appearance.name,Value=Appearance.Clone(settings.Appearance)}};choices.AddRange(Appearance.Presets().Select(theme=>new ThemeChoice{Label=theme.name,Value=theme}));choices.AddRange(settings.SavedThemes.Select(theme=>new ThemeChoice{Label="Personnel · "+theme.name,Value=theme}));var picker=new ComboBox{ItemsSource=choices,SelectedIndex=0,DisplayMemberPath="Label"};Field(body,"Choisir une ambiance",picker);var sample=new StackPanel();body.Children.Add(sample);Action preview=delegate{sample.Children.Clear();sample.Children.Add(WizardThemePreview(settings.Appearance));};picker.SelectionChanged+=delegate{var choice=picker.SelectedItem as ThemeChoice;if(choice!=null){settings.Appearance=Appearance.Clone(choice.Value);settings.Accent=settings.Appearance.accent;preview();}};body.Children.Add(Btn("Personnaliser la couleur d’accent",delegate{using(var color=new System.Windows.Forms.ColorDialog{Color=System.Drawing.ColorTranslator.FromHtml(settings.Appearance.accent),FullOpen=true})if(color.ShowDialog()==System.Windows.Forms.DialogResult.OK){settings.Appearance.accent=Appearance.Hex(Color.FromRgb(color.Color.R,color.Color.G,color.Color.B));settings.Accent=settings.Appearance.accent;preview();}}));body.Children.Add(T("Les couleurs du fond, les dégradés et l’opacité des cartes pourront être réglés précisément dans Apparence & thèmes.",12,Muted,new Thickness(0,14,0,0)));preview();}
 else if(step==2){body.Children.Add(T("Choisissez ce que vous voulez voir en ouvrant l’application. Vous pourrez déplacer et redimensionner les blocs ensuite.",13,Muted,new Thickness(0,0,0,16)));WizardCheck(body,"Afficher le message d’accueil",settings.ShowBanner,value=>settings.ShowBanner=value);WizardCheck(body,"Afficher les compteurs",settings.ShowStats,value=>settings.ShowStats=value);body.Children.Add(T("Mes blocs",12,Muted,new Thickness(0,12,0,8)));foreach(var block in settings.HomeBlocks){var item=block;WizardCheck(body,HomeLayout.Name(item.id),item.visible,value=>item.visible=value);}}
 else if(step==3){body.Children.Add(T("Gardez les sites utiles et ajoutez vos applications ou dossiers. Rien ne s’ouvrira pendant la configuration.",12,Muted,new Thickness(0,0,0,16)));var tools=new WrapPanel{Margin=new Thickness(0,0,0,16)};tools.Children.Add(Btn("+  Site web",delegate{if(settings.Links.Count>=30){error.Text="Limite : 30 sites web.";return;}var link=WizardWebLink();if(link!=null){settings.Links.Add(link);draw();}},false,true));tools.Children.Add(Btn("+  Application",delegate{if(settings.LocalShortcuts.Count>=30){error.Text="Limite : 30 raccourcis locaux.";return;}using(var picker=new System.Windows.Forms.OpenFileDialog{Title="Choisir une application",Filter="Application Windows|*.exe"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK){settings.LocalShortcuts.Add(new ModeAction{kind="exe",label=Path.GetFileNameWithoutExtension(picker.FileName),target=picker.FileName});draw();}},false,true));tools.Children.Add(Btn("+  Dossier",delegate{if(settings.LocalShortcuts.Count>=30){error.Text="Limite : 30 raccourcis locaux.";return;}using(var picker=new System.Windows.Forms.FolderBrowserDialog{Description="Choisir un dossier",ShowNewFolderButton=false})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK){string path=picker.SelectedPath;string label=Path.GetFileName(path.TrimEnd(Path.DirectorySeparatorChar));settings.LocalShortcuts.Add(new ModeAction{kind="folder",label=String.IsNullOrEmpty(label)?path:label,target=path});draw();}},false,true));body.Children.Add(tools);foreach(var link in settings.Links.ToList()){var item=link;body.Children.Add(WizardShortcutRow(item.Name,item.Url,value=>item.Name=value,delegate{settings.Links.Remove(item);draw();}));}foreach(var shortcut in settings.LocalShortcuts.ToList()){var item=shortcut;body.Children.Add(WizardShortcutRow(item.label,item.target,value=>item.label=value,delegate{settings.LocalShortcuts.Remove(item);draw();}));}capture=delegate{if(settings.Links.Any(link=>String.IsNullOrWhiteSpace(link.Na