n.label,target=action.target}).ToList(),pageKind=destination.SelectedIndex>0?"project":"",pageId=destination.SelectedIndex>0?Convert.ToString(destination.SelectedItem):""});name.Text="";chosen.Clear();return true;};body.Children.Add(Btn("Ajouter ce mode",delegate{if(addMode())draw();},false,true));capture=delegate{return String.IsNullOrWhiteSpace(name.Text)&&chosen.Count==0&&destination.SelectedIndex==0||addMode();};}
 else if(step==5){WizardCheck(body,"Ouvrir à ma connexion Windows",draft.Startup,value=>draft.Startup=value);WizardCheck(body,"Garder l’application active près de l’horloge après fermeture",settings.CloseToTray,value=>settings.CloseToTray=value);WizardCheck(body,"Activer les rappels Windows",settings.Notifications,value=>settings.Notifications=value);WizardCheck(body,"Activer Ctrl + Alt + N pour la capture rapide",settings.QuickCapture,value=>settings.QuickCapture=value);body.Children.Add(T("Routine du matin · facultatif",16,Ink,new Thickness(0,18,0,14)));bool hasAudio=!String.IsNullOrEmpty(draft.AudioSource)||File.Exists(store.AudioPath);if(!hasAudio)settings.AutoMorning=false;var audio=T(!String.IsNullOrEmpty(draft.AudioSource)?Path.GetFileName(draft.AudioSource):hasAudio?"Votre MP3 actuel sera conservé.":"Aucun MP3 choisi.",12,Muted,new Thickness(0,0,0,10));body.Children.Add(audio);CheckBox routine=null;body.Children.Add(Btn("Choisir un MP3",delegate{using(var picker=new System.Windows.Forms.OpenFileDialog{Title="Musique de la routine",Filter="Musique MP3|*.mp3"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK){if(new FileInfo(picker.FileName).Length>80L*1024*1024){error.Text="Le MP3 doit faire moins de 80 Mo.";return;}draft.AudioSource=picker.FileName;audio.Text=Path.GetFileName(picker.FileName)+" · sera copié à la fin";routine.IsEnabled=true;}},false,true));routine=WizardCheck(body,"Lancer la routine à ma connexion Windows",settings.AutoMorning,value=>settings.AutoMorning=value);routine.IsEnabled=hasAudio;WizardCheck(body,"Une seule routine automatique par jour",settings.OnceDaily,value=>settings.OnceDaily=value);WizardCheck(body,"Lire ma synthèse vocale pendant la musique",settings.Speak,value=>settings.Speak=value);WizardCheck(body,"Ouvrir Spotify après le morceau",settings.OpenSpotify,value=>settings.OpenSpotify=value);body.Children.Add(T("La routine automatique nécessite un MP3. Les volumes et la voix se règlent ensuite dans Musique & voix. Le 