 else{body.Children.Add(WizardThemePreview(settings.Appearance));foreach(string summary in new[]{settings.DisplayName+" · "+settings.AppTitle,"Thème : "+settings.Appearance.name,settings.HomeBlocks.Count(block=>block.visible)+" bloc(s) sur l’accueil",settings.Links.Count+" site(s) et "+settings.LocalShortcuts.Count+" raccourci(s) local(aux)",draft.Modes.Count+" mode(s) personnalisés","Démarrage Windows : "+(draft.Startup?"activé":"désactivé"),"Rappels Windows : "+(settings.Notifications?"activés":"désactivés"),"Routine automatique : "+(settings.AutoMorning?"activée":"désactivée")})body.Children.Add(T(summary,13,Ink,new Thickness(0,0,0,12)));body.Children.Add(T("Terminer enregistre vos choix. Vos tâches, notes, rendez-vous et fichiers existants sont conservés. Aucun mode ne sera lancé automatiquement.",12,Muted,new Thickness(0,12,0,12)));body.Children.Add(T("À retenir : Ctrl + K pour chercher, Ctrl + Alt + N pour capturer une idée.",12,AccentText));}
 body.Children.Add(error);actions.Children.Add(Btn("Plus tard",delegate{if(!store.Value.settings.Configured){bool previous=store.Value.settings.OnboardingDeferred;store.Value.settings.OnboardingDeferred=true;if(!owner.Save()){store.Value.settings.OnboardingDeferred=previous;return;}}w.DialogResult=false;},false,true));if(step>0)actions.Children.Add(Btn("Précédent",delegate{step--;draw();},false,true));Button next=null;next=Btn(step==6?"Terminer":"Suivant",delegate{if(!capture())return;if(step<6){step++;draw();return;}next.IsEnabled=false;if(owner.FinishSetup(draft))w.DialogResult=true;else next.IsEnabled=true;},true);actions.Children.Add(next);var scroll=body.Parent as ScrollViewer;if(scroll!=null)scroll.ScrollToTop();};draw();if(ShowWindow(w)==true)Go("Aujourd’hui");else Refresh();}
